@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + number : int
  + capacity : int
}

abstract class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Member {
  + memberId : string
}

class Trainer {
  + diploma : string
}

class Prospect {
}

class Intern {
}

abstract class Session {
  + date : date
  + startTime : time
}

class IndividualSession {}

class GroupSession {
  + type : string
}

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session

Person "1" -- "0..*" Member
Person "1" -- "0..*" Trainer
Person "1" -- "0..*" Prospect
Person "1" -- "0..*" Intern

Trainer --|> Person
Member --|> Person
Prospect --|> Person
Intern --|> Person

Session --|> IndividualSession
Session --|> GroupSession

GroupSession "1" -- "1" Trainer
Session "0..*" -- "0..*" Person : participation

@enduml

